def transform(grid):
    """Draw lines between aligned color-1 markers and recolor hit 2-objects."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 1]
    line = set()
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if r1 == r2:
                line.update((r1, c) for c in range(min(c1, c2), max(c1, c2) + 1))
            elif c1 == c2:
                line.update((r, c1) for r in range(min(r1, r2), max(r1, r2) + 1))
    for r, c in line:
        out[r][c] = 1
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            hit = False
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                hit |= (rr, cc) in line
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if hit:
                for rr, cc in component:
                    out[rr][cc] = 1
    return out
